package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestPackageCommentsAndExplicitBuildVariants(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	sources := map[string]string{
		"doc.go":       "// Package example provides a lint fixture.\npackage example\n",
		"variant.go":   "//go:build functional\n\npackage example\nimport \"context\"\nfunc needsContext(value int, ctx context.Context) {}\n",
		"generated.go": "// Code generated by a lint fixture. DO NOT EDIT.\npackage example\nvar MissingComment int\n",
	}
	files := make([]string, 0, len(sources))
	for name, source := range sources {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte(source), 0600); err != nil {
			t.Fatal(err)
		}
		files = append(files, path)
	}
	findings, err := collectFindings("../../revive.toml", files)
	if err != nil {
		t.Fatal(err)
	}
	if len(findings) != 1 || findings[0].RuleName != "context-as-argument" || filepath.Base(findings[0].Position.Start.Filename) != "variant.go" {
		t.Fatalf("expected only the real tagged-source finding, got %+v", findings)
	}
}
